    public async ValueTask<CommandResult> PerformAsync(string action)
    {
        var station=Package.Stations.SingleOrDefault(x=>x.Action==action)??throw new InvalidOperationException("该动作未注册实际站位。");var s=await _repository.SnapshotAsync();Safe(s);Editable(s);At(s,station.Spot);var st=State(s);var next=st;var changes=ImmutableArray.CreateBuilder<EntityChange>();var items=ImmutableArray.CreateBuilder<ItemChange>();object result=new{action,actual_spot=station.Spot};
        switch(action)
        {
            case "register_landing":Require(Sources(s,"R6-Q601-R-LANDING"),"请取得本次真实登陆说明。");next=st with{Landing=true};break;
            case "request_survey":Require(st.Landing&&Sources(s,"R6-Q601-R-BRIEFING"),"本次地方登陆和调查范围缺失。");next=st with{Briefing=true};break;
            case "inspect_basic_gear":Require(st.Briefing,"先确认当前地方调查。");var kit=s.Items.Single(i=>i.Id=="R6-local:survey_kit"&&i.OwnerKind=="warehouse"&&i.OwnerId=="R6-S02");items.Add(new(kit.Id,kit.DefinitionId,kit.OwnerKind,kit.OwnerId,"installed","R6:survey_protection",null));next=st with{BasicGear=true};break;
            case "secure_guide_markers":Require(st.Corridor=="marked_leeward"&&st.BasicGear&&Sources(s,"R6-Q601-R-FORECAST"),"背风路线、当前预报和防护包尚未核对。");next=st with{GuideMarkers=true};break;
            case "isolate_survey_instrument":Require(HasResult(s,"ENC-R6-02")&&Sources(s,"R6-Q601-R-INSTRUMENT"),"先处置独立测站危险并取得仪表说明。");next=st with{SurveyIsolation=true,SurveyRevision=st.SurveyRevision+1,SurveyCheck=null};break;
            case "test_survey":Require(st.SurveyIsolation&&st.Survey is{Corridor:"marked_leeward",ZeroChannel:"Z",ZeroReading:0,ReferenceChannel:"R",ReferenceReading:10,RiskScope:"current_overload_amplification",Window:"current_survey_stage"}&&st.Survey.Revision==st.SurveyRevision&&HasResult(s,"ENC-R6-02"),"当前隔离、Z0/R10、范围和测量版本不能以旧读数替代。");next=st with{SurveyCheck=st.SurveyRevision};break;
            case "inspect_inner_return":Require(st.SurveyCurrent&&HasResult(s,"ENC-R6-01")&&HasResult(s,"ENC-R6-02")&&Sources(s,"R6-Q601-R-RETURN"),"测站当前读数、危险处置及内侧门闩原文未共同成立。");next=st with{ReturnAnchor=true};break;
            case "inspect_cargo_manifest":Require(Closed(s,"Q-601")&&Sources(s,"R6-Q603-R-MANIFEST"),"调查闭合后才能核对这批受保护货单。");foreach(var src in Engineering.Rules.Sources.Values.Where(x=>x.Id.StartsWith("BASE-TWR-R6-",StringComparison.Ordinal)))for(int n=1;n<=src.Quantity;n++){var item=s.Items.Single(i=>i.Id==StockId(src.Id,n)&&i.OwnerKind=="warehouse"&&i.OwnerId=="R6:facility:"+src.Id);items.Add(new(item.Id,item.DefinitionId,item.OwnerKind,item.OwnerId,"warehouse","R6:protected_cart",null));}changes.Add(BranchOperations.Change(s,"R6:cargo","frontier_cargo",new FrontierCargoState("inspected","R6-S05",items.Select(i=>i.Id).ToImmutableArray(),Actor(s).ActionClock,false)));break;
            case "start_outer_segment":Require(st.CargoPlan is not null&&HasResult(s,"ENC-R6-03")&&BranchOperations.Read<FrontierCargoState>(s,"R6:cargo") is{Stage:"inspected"} c&&c.ItemIds.Length==4,"真实货组、明确段计划及首段护送处置未共同成立。");next=st with{CargoStage="outer"};var cargo=BranchOperations.Read<FrontierCargoState>(s,"R6:cargo")!;changes.Add(BranchOperations.Change(s,"R6:cargo","frontier_cargo",cargo with{Stage="in_transit",ActorClock=Actor(s).ActionClock}));changes.Add(BranchOperations.Change(s,CargoSegment,"transport_segment",new TransportSegment(CargoSegment,"R6-S05","R6-S07",true,false)));break;
            case "continue_ridge_segment":Require(st.CargoStage=="outer"&&HasResult(s,"ENC-R6-04")&&BranchOperations.Read<FrontierCargoState>(s,"R6:cargo") is{Stage:"in_transit",Scene:"R6-S06",SafelyDeposited:false},"必须由真实外线货组完成第二段处置。");next=st with{CargoStage="ridge"};break;
            case "control_field_device":throw new InvalidOperationException("护场器须按专用命令实际断输入、固定外侧制动并核零能，单按钮不能补齐。");
            case "protect_current_cargo":Require(st.FieldGuardControlled&&st.CargoStage=="ridge"&&BranchOperations.Read<FrontierCargoState>(s,"R6:cargo") is{Stage:"in_transit",Scene:"R6-S07",SafelyDeposited:false},"护场器与当前实际货载缺失。");next=st with{CargoProtected=true,TowerRevision=st.TowerRevision+1,TowerCheck=null};break;
            case "isolate_platform":Require(st.FieldGuardControlled&&st.CargoProtected&&HasResult(s,"ENC-R6-05"),"主体处置不替代先执行的护场器与货物保护。");next=st with{PlatformIsolated=true,TowerRevision=st.TowerRevision+1,TowerCheck=null};break;
            case "receive_base_packet":Require(st.PlatformIsolated&&st.CargoProtected&&HasResult(s,"ENC-R6-04")&&Sources(s,"R6-Q603-R-LOCAL")&&BranchOperations.Read<FrontierCargoState>(s,"R6:cargo") is{Stage:"in_transit",Scene:"R6-S07",ItemIds.Length:4,SafelyDeposited:false},"四件实物未由配对出口实际抵达安全接收点。");var cc=BranchOperations.Read<FrontierCargoState>(s,"R6:cargo")!;foreach(string id in cc.ItemIds){var item=s.Items.Single(i=>i.Id==id&&i.OwnerKind=="warehouse"&&i.OwnerId=="R6:protected_cart");items.Add(new(item.Id,item.DefinitionId,item.OwnerKind,item.OwnerId,"warehouse","R6-S07:received_base",null));}next=st with{CargoDelivered=true,CargoStage="received",TowerRevision=st.TowerRevision+1,TowerCheck=null};changes.Add(BranchOperations.Change(s,"R6:cargo","frontier_cargo",cc with{Stage="received",SafelyDeposited=true}));changes.Add(BranchOperations.Change(s,CargoSegment,"transport_segment",new TransportSegment(CargoSegment,"R6-S05","R6-S07",false,true)));break;
            case "inspect_ridge_return":Require(st.CargoDelivered&&st.PlatformIsolated&&HasResult(s,"ENC-R6-05"),"实际收货与平台隔离未完成。");next=st with{TowerReturn=true};break;
            case "test_ridge_tower":Require(st.CargoDelivered&&st.PlatformIsolated&&st.TowerReturn&&HasResult(s,"ENC-R6-05"),"当前实际收货、隔离与返程缺失。");next=st with{TowerCheck=st.TowerRevision};var readiness=BranchOperations.Read<TowerReadiness>(s,"readiness:TWR-R6")??new("TWR-R6",false,false,null,false,false,false,null);changes.Add(BranchOperations.Change(s,"readiness:TWR-R6","tower_readiness",readiness with{Safe=true}));result=new TowerSafety("TWR-R6",true,"R6:actual_ridge_configuration:"+st.TowerRevision);break;
            case "deposit_cargo_safely":Require(BranchOperations.Read<FrontierCargoState>(s,"R6:cargo") is{Stage:"in_transit",Scene:"R6-S06",SafelyDeposited:false},"当前没有可交接的外线货组。");var dep=BranchOperations.Read<FrontierCargoState>(s,"R6:cargo")!;foreach(string id in dep.ItemIds){var item=s.Items.Single(i=>i.Id==id&&i.OwnerId=="R6:protected_cart");items.Add(new(item.Id,item.DefinitionId,item.OwnerKind,item.OwnerId,"warehouse","R6-S06:cart_keeper",null));}next=st with{CargoStage="deposited"};changes.Add(BranchOperations.Change(s,"R6:cargo","frontier_cargo",dep with{Stage="deposited",SafelyDeposited=true}));changes.Add(BranchOperations.Change(s,CargoSegment,"transport_segment",new TransportSegment(CargoSegment,"R6-S05","R6-S07",false,false)));break;
            case "inspect_six_tower_overview":Require(Closed(s,"Q-601"),"调查后才有本轮六塔工作。");result=new{towers=await Engineering.ReadinessAsync(),requirements_only=false,actual_receipts=s.Receipts.Where(r=>r.ActionType=="engineering_work_result").Select(r=>r.ReceiptId).ToArray()};break;
            case "inspect_departure_qualification":Require(Closed(s,"Q-602")&&Closed(s,"Q-603"),"六塔基础与风脊真实闭合后进入起航核对。");next=st with{QualificationViewed=true};result=await Readiness.ViewAsync();break;
            case "inspect_facility_contract":Require(Closed(s,"Q-601"),"先完成当前测站调查。");result=new{contracts=Package.Facilities,actual_inspection_required=true};break;
            case "propose_optional_settlement_contact":case "inspect_optional_shared_maintenance":result=new{registered=false,remaining="该可选增补尚无独立交付生产者；本次只保存到场提议，未改变基本资格。",actual_spot=station.Spot};break;
            default:throw new InvalidOperationException("此动作需要专用结构化参数或真实提交预览，不可由通用按钮代执行。");
        }
        changes.Add(Change(s,next));return await Commit(s,action=="test_ridge_tower"?"tower_safety_verified":"chapter_six_station_action",changes.ToImmutable(),result,items:items.ToImmutable());
    }
    public async ValueTask<CommandResult> ChooseCorridorAsync(string route){var s=await _repository.SnapshotAsync();Safe(s);Editable(s);At(s,"R6-S03.forecast");Require(State(s).Briefing&&State(s).BasicGear&&Sources(s,"R6-Q601-R-FORECAST")&&route=="marked_leeward","必须同时核对当前预报与地标；低切口积雾、裸脊阵风未获安全核验。");return await Commit(s,"chapter_six_corridor_selected",[Change(s,State(s) with{Corridor=route})],new{route,current_window="current_survey_stage"});}
    public async ValueTask<CommandResult> ControlFieldDeviceAsync(string step){var s=await _repository.SnapshotAsync();Safe(s);Editable(s);At(s,"R6-S07.field_device");var st=State(s);Require(st.CargoStage=="ridge"&&Sources(s,"R6-Q603-R-PLATFORM"),"真实当前货组与外侧装置规则未取得。");string[] steps=["disconnect_field_input","fix_external_brake","verify_zero_field_energy"];Require(st.FieldDeviceStep<3&&step==steps[st.FieldDeviceStep],"须依次实际断输入、固定制动、核零能；主机压力不代此操作。");int n=st.FieldDeviceStep+1;return await Commit(s,"chapter_six_field_device_control_step",[Change(s,st with{FieldDeviceStep=n,FieldGuardControlled=n==3,TowerRevision=st.TowerRevision+1,TowerCheck=null})],new{step,n,device="r6-field-device",actual_external_stand="R6-S07.field_device",controlled=n==3});}
    public async ValueTask<CommandResult> ConfigureSurveyAsync(string zero,int z,string reference,int r,string risk,string window){var s=await _repository.SnapshotAsync();Safe(s);Editable(s);At(s,"R6-S04.calibration");var st=State(s);Require(st.SurveyIsolation&&zero=="Z"&&z==0&&reference=="R"&&r==10&&risk=="current_overload_amplification"&&window=="current_survey_stage","仪表标签/隔离/范围/窗口须对应原始刻度；不接受全雾成因或风暴准确钟点。");long rev=st.SurveyRevision+1;return await Commit(s,"chapter_six_survey_configuration",[Change(s,st with{Survey=new(st.Corridor,zero,z,reference,r,risk,window,rev),SurveyRevision=rev,SurveyCheck=null})],new{current_revision=rev});}
    public async ValueTask<CommandResult> PlanCargoAsync(string[] resourceIds,string[] escorts,string destination,string fallback){var s=await _repository.SnapshotAsync();Safe(s);Editable(s);At(s,"R6-S05.segment");var st=State(s);var cargo=BranchOperations.Read<FrontierCargoState>(s,"R6:cargo");Require(Closed(s,"Q-601")&&Quest(s,"Q-603") is{Lifecycle:QuestLifecycle.Active}&&cargo is{Stage:"inspected",ItemIds.Length:4}&&resourceIds.Order().SequenceEqual(cargo.ItemIds.Order())&&escorts.Order().SequenceEqual(new[]{"ROLE-R6-CARGO-WATCH","ROLE-R6-CART-DRIVER"})&&destination=="R6-S07"&&fallback=="previous_safe_segment"&&Sources(s,"R6-Q603-R-MANIFEST","R6-Q603-R-SEGMENTS"),"货组序号、两个当前护送岗、目的地或上一安全段备用方案不符。");return await Commit(s,"chapter_six_cargo_plan",[Change(s,st with{CargoPlan=new("TWR-R6",resourceIds.ToImmutableArray(),escorts.ToImmutableArray(),destination,fallback,"first")})],new{actual_item_ids=resourceIds,escorts,destination,fallback});}
    public async ValueTask<CommandResult> ConfirmPreparationDirectionAsync(string direction){var s=await _repository.SnapshotAsync();Safe(s,false);Editable(s);At(s,"R6-S08.qualification");Require(State(s).QualificationViewed&&direction is "continue_preparation" or "accept_base_directions","先看公开缺项，再明确继续准备或接受两个基础方向。");return await Commit(s,"chapter_six_preparation_direction",[Change(s,State(s) with{PreparationDecision=direction})],new{direction,final_policy="not_selected"});}
    public ValueTask<CommandResult> VerifyRiskRegisterAsync()=>WithForeground(()=>VerifyRiskRegisterAsyncCore());
    private async ValueTask<CommandResult> VerifyRiskRegisterAsyncCore(){var s=await _repository.SnapshotAsync();Safe(s,false);Editable(s);At(s,"R6-S08.commitments");var commitments=s.Entities.Where(e=>e.Kind=="high_risk_commitment").Select(e=>e.Id).Order().ToImmutableArray();var transports=s.Entities.Where(e=>e.Kind=="transport_segment").Select(e=>e.Id).Order().ToImmutableArray();Require(commitments.All(id=>BranchOperations.Read<HighRiskCommitment>(s,id) is{} c&&(!c.Accepted||!c.OnsiteRequired||c.SafelyHandedOver||c.ExplicitlySuspended))&&transports.All(id=>BranchOperations.Read<TransportSegment>(s,id) is{} t&&(!t.CargoInTransit||t.Completed)),"必须到场承诺须真实交接/暂缓，实际货载须完成或安全托管。");long ver=(BranchOperations.Read<CurrentRiskRegister>(s,"final:commitments")?.Version??0)+1;var proof=await Commit(s,"high_risk_register_verified",[],new RiskRegisterVerification(ver,commitments,transports));Require(proof.Receipt is not null&&proof.Status==CommitStatus.Committed,"当前风险登记未签发。");s=await _repository.SnapshotAsync();return await Commit(s,"chapter_six_risk_register_recorded",[BranchOperations.Change(s,"final:commitments","risk_register",new CurrentRiskRegister(ver,commitments,transports,proof.Receipt!.Id.Value.ToString()))],new{version=ver,actual_source_receipt=proof.Receipt.Id.Value.ToString()});}
    public ValueTask<CommandResult> SealPreparationAsync()=>WithForeground(()=>SealPreparationAsyncCore());
    private async ValueTask<CommandResult> SealPreparationAsyncCore(){var s=await _repository.SnapshotAsync();Safe(s,false);At(s,"R6-S08.qualification");Require(State(s).QualificationViewed&&State(s).PreparationDecision is "continue_preparation" or "accept_base_directions","须先公开资格并确认准备方向。");Require(QuestSources(s,"Q-604"),"请在实际站位取得当前公开资格、风险与起航交接材料。");var d=await _repository.GetDraftAsync(Package.WritingTasks.Single(w=>w.Quest=="Q-604").Id);var meaning=BranchOperations.Read<Mist.Core.ChapterTwo.ChapterWorldMeaning>(s,"proposal:Q-604");Require(meaning is not null&&meaning.DraftHash==d?.Hash&&meaning.Fields.GetValueOrDefault("policy")=="not_selected"&&meaning.Fields.GetValueOrDefault("risks")=="current_handed_over"&&meaning.Fields.GetValueOrDefault("preparation")==State(s).PreparationDecision,"当前交接正文意思须与风险和准备方向一致；编辑后旧确认失效。");return await Readiness.SealPreparationAsync();}
